-- Cached counters.
UPDATE problems p SET vote_count = (SELECT count(*) FROM problem_votes v WHERE v.problem_id = p.id);
UPDATE ideas i SET vote_count = (SELECT count(*) FROM idea_votes v WHERE v.idea_id = i.id);
UPDATE idea_comments c SET score = COALESCE((SELECT sum(value) FROM idea_comment_votes v WHERE v.comment_id = c.id), 0);
