INSERT INTO problems (id, user_id, title, description, created_at, updated_at) VALUES
    ('d0000000-0000-7000-8000-000200000001', 'd0000000-0000-7000-8000-000100000002', 'Cafeteria queues eat half my lunch break', 'Between 12:00 and 13:00 the queue at the campus cafeteria is 20+ minutes. By the time I get food I have 10 minutes to eat before class.', now() - interval '2 hours', now() - interval '2 hours'),
    ('d0000000-0000-7000-8000-000200000002', 'd0000000-0000-7000-8000-000100000004', 'No easy way to find study partners for a module', 'WhatsApp groups are chaos. I want to find 2–3 people doing the same module who want to study at the same times.', now() - interval '5 hours', now() - interval '5 hours'),
    ('d0000000-0000-7000-8000-000200000003', 'd0000000-0000-7000-8000-000100000006', 'Textbooks are way too expensive', 'Some prescribed books cost R1500+. Seniors have them lying around but there is no trusted place to buy second-hand.', now() - interval '9 hours', now() - interval '9 hours'),
    ('d0000000-0000-7000-8000-000200000004', 'd0000000-0000-7000-8000-000100000003', 'Load-shedding kills group project meetings', 'Half the team drops off calls when their area goes down. We lose momentum and deadlines slip.', now() - interval '20 hours', now() - interval '20 hours'),
    ('d0000000-0000-7000-8000-000200000005', 'd0000000-0000-7000-8000-000100000007', 'Lift clubs to campus are hard to organise', 'Lots of students drive in from the same suburbs alone. Petrol is expensive and parking is full by 8am.', now() - interval '28 hours', now() - interval '28 hours'),
    ('d0000000-0000-7000-8000-000200000006', 'd0000000-0000-7000-8000-000100000008', 'Hard to know which lecturers are available when', 'Consultation hours are posted in random places. I walk to an office and nobody is there.', now() - interval '34 hours', now() - interval '34 hours'),
    ('d0000000-0000-7000-8000-000200000007', 'd0000000-0000-7000-8000-000100000001', 'Student businesses have no place to advertise', 'Lots of students sell food, do nails, fix laptops… but you only hear about them by word of mouth.', now() - interval '40 hours', now() - interval '40 hours'),
    ('d0000000-0000-7000-8000-000200000008', 'd0000000-0000-7000-8000-000100000002', 'Campus Wi-Fi dead zones', 'The library second floor and the back labs have almost no signal. Hard to submit anything there.', now() - interval '52 hours', now() - interval '52 hours'),
    ('d0000000-0000-7000-8000-000200000009', 'd0000000-0000-7000-8000-000100000006', 'Budgeting on a student allowance is hard', 'NSFAS / bursary money comes in once and it is gone by week 3. Existing budgeting apps are not made for students.', now() - interval '60 hours', now() - interval '60 hours'),
    ('d0000000-0000-7000-8000-000200000010', 'd0000000-0000-7000-8000-000100000004', 'Events on campus are poorly advertised', 'I find out about hackathons and talks the day after they happen.', now() - interval '75 hours', now() - interval '75 hours'),
    ('d0000000-0000-7000-8000-000200000011', 'd0000000-0000-7000-8000-000100000003', 'No mentors for side projects', 'I have ideas but nobody to sanity-check the tech or business side before I sink months into it.', now() - interval '90 hours', now() - interval '90 hours'),
    ('d0000000-0000-7000-8000-000200000012', 'd0000000-0000-7000-8000-000100000007', 'Printing credits run out at the worst time', 'Always the night before a submission. Topping up requires going to the front desk during office hours.', now() - interval '110 hours', now() - interval '110 hours')
