INSERT INTO ideas (id, user_id, title, description, visibility, project_id, created_at, updated_at) VALUES
    ('d0000000-0000-7000-8000-000300000001', 'd0000000-0000-7000-8000-000100000001', 'Pre-order app for the cafeteria', 'Order and pay from your phone, pick a 5-minute pickup slot, skip the queue. The cafeteria sees a live list of orders per slot.', 'public', 'd0000000-0000-7000-8000-000500000001', now() - interval '1 hours', now() - interval '1 hours'),
    ('d0000000-0000-7000-8000-000300000002', 'd0000000-0000-7000-8000-000100000002', 'Study-buddy matcher', 'Pick your modules and free times, get matched with 2–3 people. Chat opens automatically; the group dissolves after exams.', 'public', NULL, now() - interval '4 hours', now() - interval '4 hours'),
    ('d0000000-0000-7000-8000-000300000003', 'd0000000-0000-7000-8000-000100000006', 'Verified second-hand textbook market', 'Only Eduvos accounts can list. Seller drops the book at the Hub, buyer collects. No scams, no meeting strangers.', 'public', 'd0000000-0000-7000-8000-000500000002', now() - interval '8 hours', now() - interval '8 hours'),
    ('d0000000-0000-7000-8000-000300000004', 'd0000000-0000-7000-8000-000100000003', 'Offline-first project board', 'A task board that syncs when you come back online, with SMS fallback for "I am down, will catch up".', 'private', NULL, now() - interval '18 hours', now() - interval '18 hours'),
    ('d0000000-0000-7000-8000-000300000005', 'd0000000-0000-7000-8000-000100000007', 'Campus lift club finder', 'Match drivers and passengers by suburb and class times. Split petrol cost automatically.', 'public', 'd0000000-0000-7000-8000-000500000003', now() - interval '26 hours', now() - interval '26 hours'),
    ('d0000000-0000-7000-8000-000300000006', 'd0000000-0000-7000-8000-000100000001', 'Student business directory in EduvosMarket', 'Every Hub venture and student side-hustle gets a page. Filters for food, services, tech. Reviews from verified students.', 'public', 'd0000000-0000-7000-8000-000500000004', now() - interval '38 hours', now() - interval '38 hours'),
    ('d0000000-0000-7000-8000-000300000007', 'd0000000-0000-7000-8000-000100000008', 'Lecturer availability status', 'Lecturers tap "in office / away" on their phone; students see live status and a booking slot.', 'public', NULL, now() - interval '33 hours', now() - interval '33 hours'),
    ('d0000000-0000-7000-8000-000300000008', 'd0000000-0000-7000-8000-000100000004', 'One campus events calendar with push alerts', 'Clubs and the Hub post events once; students follow categories and get a push the day before.', 'public', NULL, now() - interval '70 hours', now() - interval '70 hours'),
    ('d0000000-0000-7000-8000-000300000009', 'd0000000-0000-7000-8000-000100000006', 'Envelope budgeting for bursary money', 'Split your allowance into envelopes on day one (food, transport, data). The app nags you when an envelope runs low.', 'public', 'd0000000-0000-7000-8000-000500000005', now() - interval '58 hours', now() - interval '58 hours'),
    ('d0000000-0000-7000-8000-000300000010', 'd0000000-0000-7000-8000-000100000002', 'Wi-Fi heatmap crowd-sourced by students', 'The app samples signal strength in the background and builds a heatmap IT can act on.', 'public', NULL, now() - interval '50 hours', now() - interval '50 hours'),
    ('d0000000-0000-7000-8000-000300000011', 'd0000000-0000-7000-8000-000100000001', 'Mentor office hours marketplace', 'Alumni and seniors offer 30-minute slots. Students book with a short description of their project.', 'private', NULL, now() - interval '85 hours', now() - interval '85 hours'),
    ('d0000000-0000-7000-8000-000300000012', 'd0000000-0000-7000-8000-000100000003', 'Printing credit top-up via SnapScan', 'Scan a QR on the printer, pay, credits appear instantly.', 'public', NULL, now() - interval '105 hours', now() - interval '105 hours')
