INSERT INTO idea_comments (id, idea_id, parent_id, user_id, comment_type, content, depth, deleted_at, created_at, updated_at) VALUES
    ('d0000000-0000-7000-8000-000400000001', 'd0000000-0000-7000-8000-000300000001', NULL, 'd0000000-0000-7000-8000-000100000004', '0192f000-0000-7000-8000-000000000004', 'I would use this every single day. Take my money.', 0, NULL, now() - interval '0.9 hours', now() - interval '0.9 hours'),
    ('d0000000-0000-7000-8000-000400000002', 'd0000000-0000-7000-8000-000300000001', NULL, 'd0000000-0000-7000-8000-000100000003', '0192f000-0000-7000-8000-000000000002', 'How does the cafeteria get the orders? Do they need a tablet?', 0, NULL, now() - interval '0.8 hours', now() - interval '0.8 hours'),
    ('d0000000-0000-7000-8000-000400000003', 'd0000000-0000-7000-8000-000300000001', 'd0000000-0000-7000-8000-000400000002', 'd0000000-0000-7000-8000-000100000001', '0192f000-0000-7000-8000-000000000001', 'Yes, a cheap Android tablet with a web view. Orders grouped by pickup slot.', 1, NULL, now() - interval '0.7 hours', now() - interval '0.7 hours'),
    ('d0000000-0000-7000-8000-000400000004', 'd0000000-0000-7000-8000-000300000001', 'd0000000-0000-7000-8000-000400000003', 'd0000000-0000-7000-8000-000100000003', '0192f000-0000-7000-8000-000000000004', 'Nice, that is simple enough to pilot next month.', 2, NULL, now() - interval '0.6 hours', now() - interval '0.6 hours'),
    ('d0000000-0000-7000-8000-000400000005', 'd0000000-0000-7000-8000-000300000001', NULL, 'd0000000-0000-7000-8000-000100000006', '0192f000-0000-7000-8000-000000000003', 'Payments could be tricky. Card fees on R35 meals add up.', 0, NULL, now() - interval '0.5 hours', now() - interval '0.5 hours'),
    ('d0000000-0000-7000-8000-000400000006', 'd0000000-0000-7000-8000-000300000001', 'd0000000-0000-7000-8000-000400000005', NULL, '0192f000-0000-7000-8000-000000000001', '[deleted]', 1, now() - interval '0.3 hours', now() - interval '0.4 hours', now() - interval '0.4 hours'),
    ('d0000000-0000-7000-8000-000400000007', 'd0000000-0000-7000-8000-000300000001', 'd0000000-0000-7000-8000-000400000006', 'd0000000-0000-7000-8000-000100000001', '0192f000-0000-7000-8000-000000000001', 'We could start with a prepaid wallet you top up once a week.', 2, NULL, now() - interval '0.2 hours', now() - interval '0.2 hours'),
    ('d0000000-0000-7000-8000-000400000008', 'd0000000-0000-7000-8000-000300000002', NULL, 'd0000000-0000-7000-8000-000100000008', '0192f000-0000-7000-8000-000000000001', 'Add a "quiet study" vs "discussion" preference!', 0, NULL, now() - interval '3 hours', now() - interval '3 hours'),
    ('d0000000-0000-7000-8000-000400000009', 'd0000000-0000-7000-8000-000300000003', NULL, 'd0000000-0000-7000-8000-000100000002', '0192f000-0000-7000-8000-000000000002', 'Would the Hub be OK storing books temporarily?', 0, NULL, now() - interval '7 hours', now() - interval '7 hours'),
    ('d0000000-0000-7000-8000-000400000010', 'd0000000-0000-7000-8000-000300000003', 'd0000000-0000-7000-8000-000400000009', 'd0000000-0000-7000-8000-000100000005', '0192f000-0000-7000-8000-000000000004', 'We have a locker room we can use. Come see me.', 1, NULL, now() - interval '6 hours', now() - interval '6 hours'),
    ('d0000000-0000-7000-8000-000400000011', 'd0000000-0000-7000-8000-000300000006', NULL, 'd0000000-0000-7000-8000-000100000005', '0192f000-0000-7000-8000-000000000004', 'This is exactly what the Hub needs.', 0, NULL, now() - interval '30 hours', now() - interval '30 hours')
